/** com.khnp.pels.api.TstEventStrokeByPageList */
SELECT T1.EVENT_SNO,
       T2.LINE_PTH_DCR
  FROM GE_PL_EVENT01_M T1
       JOIN GE_PL_EVENT01_D T2
            ON T1.EVENT_SNO = T2.EVENT_SNO
 WHERE T1.PWPL_ID = #{pwplId, jdbcType=VARCHAR}
   AND T1.CHCK_SNO = #{chckSno, jdbcType=BIGINT}
   AND T1.PAGE_CNT = #{pageCnt, jdbcType=INTEGER}
 ORDER
    BY T1.EVENT_CRTE_DT
     , T1.EVENT_SNO

SELECT CHCK_EVENT_SEQ.NEXTVAL
  FROM DUAL
CONNECT BY LEVEL <= #{value, jdbcType=INTEGER}

mapper.insert:
/** com.khnp.pels.api.TstEventBatchInsert */
INSERT
  INTO GE_PL_EVENT01_M
     ( EVENT_SNO
     , EVENT_SQNO
     , PWPL_ID
     , CHCK_SNO
     , PAGE_CNT
     , INSRTN_PAGE_CNT
     , PDF_PAGE_CNT
     , EVENT_TRGT_ID
     , USER_ID
     , USER_FNM
     , CHKPR_BLNG_JBPS_NM
     , EVENT_CRTE_DT
     )
VALUES
     ( #{eventSno, jdbcType=BIGINT}
     , #{eventTypSqno, jdbcType=INTEGER}
     , #{pwplId, jdbcType=VARCHAR}
     , #{chckSno, jdbcType=BIGINT}
     , #{pageCnt, jdbcType=INTEGER}
     , #{insrtnPageCnt, jdbcType=INTEGER}
     , #{pdfPageCnt, jdbcType=INTEGER}
     , #{eventTrgtId, jdbcType=VARCHAR}
     , #{userId, jdbcType=VARCHAR}
     , #{userFnm, jdbcType=VARCHAR}
     , #{chkprBlngJbpsNm, jdbcType=VARCHAR}
     , TO_TIMESTAMP(#{eventCrteDt, jdbcType=VARCHAR},'YYYY-MM-DD"T"HH24:MI:SS.FF3')
     )

/** com.khnp.pels.api.TstEventInsert */

    SELECT CHCK_EVENT_SEQ.NEXTVAL FROM DUAL

INSERT
  INTO GE_PL_EVENT01_M
     ( EVENT_SNO
     , EVENT_SQNO
     , PWPL_ID
     , CHCK_SNO
     , PAGE_CNT
     , INSRTN_PAGE_CNT
     , PDF_PAGE_CNT
     , EVENT_TRGT_ID
     , USER_ID
     , USER_FNM
     , CHKPR_BLNG_JBPS_NM
     , EVENT_CRTE_DT
     )
VALUES
     ( #{eventSno, jdbcType=BIGINT}
     , #{eventTypSqno, jdbcType=INTEGER}
     , #{pwplId, jdbcType=VARCHAR}
     , #{chckSno, jdbcType=BIGINT}
     , #{pageCnt, jdbcType=INTEGER}
     , #{insrtnPageCnt, jdbcType=INTEGER}
     , #{pdfPageCnt, jdbcType=INTEGER}
     , #{eventTrgtId, jdbcType=VARCHAR}
     , #{userId, jdbcType=VARCHAR}
     , #{userFnm, jdbcType=VARCHAR}
     , #{chkprBlngJbpsNm, jdbcType=VARCHAR}
