     )

/** com.khnp.pels.api.TstEventStrokeInsert */
INSERT
  INTO GE_PL_EVENT01_D
     ( EVENT_SNO
     , X_CRDNT
     , Y_CRDNT
     , LINE_PTH_DCR
     , LINE_SNO
     , LINE_ETT
     )
VALUES
     ( #{eventSno, jdbcType=BIGINT}
     , #{xCrdnt, jdbcType=NUMERIC}
     , #{yCrdnt, jdbcType=NUMERIC}
     , #{linePthDcr, jdbcType=BLOB}
     , #{lineSno, jdbcType=INTEGER}
     , #{lineEtt, jdbcType=NUMERIC}
     )

/** com.khnp.pels.api.TstEventImageInsert */
INSERT
  INTO GE_PL_EVENT02_D
     ( EVENT_SNO
     , X_CRDNT
     , Y_CRDNT
     , WDTH_SZ
     , HGHT_SZ
     , URL_INFO
     )
VALUES
     ( #{eventSno, jdbcType=BIGINT}
     , #{xCrdnt, jdbcType=NUMERIC}
     , #{yCrdnt, jdbcType=NUMERIC}
     , #{wdthNumv, jdbcType=NUMERIC}
     , #{hdthNumv, jdbcType=NUMERIC}
     , #{urlInfo, jdbcType=VARCHAR}
     )
